mapper.select:
SELECT COUNT(*)
FROM reservation r
JOIN space   s ON r.s_idx = s.s_idx
JOIN branch  b ON s.b_idx = b.b_idx
JOIN user    u ON r.u_idx = u.u_idx
WHERE b.p_idx = #{partnerIdx}

    AND DATE(r.r_start_time) >= #{vo.startDate}


    AND DATE(r.r_start_time) <= #{vo.endDate}


    AND r.r_status = #{vo.statusFilter}


    AND r.s_idx = #{vo.spaceFilter}


    AND u.u_name LIKE CONCAT('%', #{vo.searchWord}, '%')

SELECT r.r_idx AS res_idx, CONCAT('RES-', LPAD(r.r_idx, 6, '0')) AS res_code, DATE_FORMAT(r.r_start_time, '%Y-%m-%d %H:%i') AS res_start_time, DATE_FORMAT(r.r_end_time, '%Y-%m-%d %H:%i') AS res_end_time, r.r_headcount AS res_headcount, r.r_total_price AS res_total_price, r.r_status AS res_status, DATE_FORMAT(r.r_created, '%Y-%m-%d %H:%i') AS res_created, u.u_name AS user_name, u.u_phone AS user_phone, s.s_idx AS spc_idx, s.s_name AS spc_name, s.s_type AS spc_type, b.b_idx AS brn_idx, b.b_name AS brn_name FROM reservation r JOIN space s ON r.s_idx = s.s_idx JOIN branch b ON s.b_idx = b.b_idx JOIN user u ON r.u_idx = u.u_idx WHERE b.p_idx = #{partnerIdx}
AND DATE(r.r_start_time) >= #{vo.startDate}
AND DATE(r.r_start_time) <= #{vo.endDate}
AND r.r_status = #{vo.statusFilter}
AND r.s_idx = #{vo.spaceFilter}
AND u.u_name LIKE CONCAT('%', #{vo.searchWord}, '%')
ORDER BY r.r_created DESC LIMIT #{numPerPage} OFFSET #{offset}
